ll mod=1e9+7;



ll mul(ll a,ll b){

  return (a*b)%mod;

}



int bit[MAX_N];

void add(int i,int x){

  i++;



  while(i<MAX_N){

    bit[i]+=x;

    i+=(i&-i);

  }

}



int sum(int i){

  i++;



  int res=0;

  while(i){

    res+=bit[i];

    i-=(i&-i);

  }

  return res;

}



