ll fact[MAX_N];

int t[MAX_N];



int main(){

  fact[0]=1;

  for(int i=1;i<MAX_N;i++)

    fact[i]=mul(fact[i-1],i);



  while(1){

    scanf("%lld",&N);

    if(N==0)break;

    scanf("%lld",&R);

    memset(bit,0,sizeof(bit));

    for(int i=0;i<N;i++)t[i]=i;



    for(int i=0;i<R;i++){

      scanf("%lld %lld",&a,&b);

      a--,b--;

      swap(t[a],t[b]);

