using namespace std;

int d, n;

vector <int> a, e, r;

vector <vector <int>> memo;

const int INF = 1000000000;



void rec(int c = 0, int exp = 0, int end = d) {

	if (memo[exp][end] <= c) return;

	memo[exp][end] = c;



	rep (i, n) {

		if (exp < r[i]) continue;

		rec(c + 1, min(exp + e[i], 100), max(end - a[i], 0));

	}

}



