int64 dfs(int i,int cnt){



  int rec = 0;



  if(cnt == b.size())return 1;



  if(memo[i][cnt] != -1)return memo[i][cnt];



  for(int j = i + 1;j < t.size();j++){



    if(t[j] == b[cnt])rec = (rec + dfs(j,cnt + 1)) % 1000000007;



  }



  return memo[i][cnt] = rec % 1000000007;



}

