void dij(int s){

    fill(go,go+101,10000000);

    fill(used,used+101,false);

    go[s]=0;

    while(true){

        int v=-1;

        for(int i=0;i<100;i++){

            if(!used[i]&&(v==-1||go[i]<go[v]))v=i;

        }

        if(v==-1)break;

        used[v]=true;

        for(int i=0;i<100;i++){

            go[i]=min(go[i],go[v]+cost[v][i]);

        }

    }

}

