                if(go[b-1]!=10000000)cout<<go[b-1]<<endl;

                else cout<<-1<<endl;

            }

            else {

                cin>>c>>d>>e;

                cost[c-1][d-1]=min(cost[c-1][d-1],e);

                cost[d-1][c-1]=min(cost[d-1][c-1],e);

            }

        }

    }

    return 0;

}

