      }

    }



    while(k--){

      cin >> req;



      if(req){

	cin >> c >> d >> e;

	if(e < map[c][d]) map[c][d] = map[d][c] = e;

      }



      else{

	cin >> a >> b;

	if((ans = dik(a, b)) != MAX) cout << ans << endl;

	else cout << "-1" << endl;

      }

    }



  }

  return 0;

}

