      //  cout <<"now + M[i] = " << now + M[i]<<   " d[now + M[i]] = " << d[now + M[i]] << " d[now] =  " <<  d[now] << endl;//





      if(M[i] >= 0){

	sum += d[now + M[i]] - d[now];  

	//	cout << "! N = " << d[now + M[i]] - d[now] << endl;//

      }

      else{

	sum += d[now] - d[now + M[i]];

	//	cout << "? N = " <<  d[now] - d[now + M[i]]  << endl;//

      }



      now = now + M[i];//



    }

    cout << sum % 100000 << endl;

  }



  return 0;

}

