ll rec(ll x){

	if(dp[x]!=-1) return dp[x];

	ll res=l-a[x];

	ll lef=0,rig=0;



	auto ok=[](ll z){return 0<=z&&z<n;};



	if(ok(x-1)&&a[x-1]>a[x]) lef=rec(x-1);

	if(ok(x+1)&&a[x+1]>a[x]) rig=rec(x+1);



	return res+max(lef,rig);

}



