		arr.resize(n + 2);

		for (int i = 0; i < n; i++)

		{

			cin >> arr[i + 1];

		}



		int ans = 0;

		for (int i = 1; i < n + 1; i++)

		{

			ans = max(ans, dfs(i));

		}

		cout << ans << endl;

	}

	return 0;

}

