		sort(X[i].begin(),X[i].end());

		reverse(X[i].begin(),X[i].end());

	}

	int sum[10][2001];

	for(int i=0;i<10;i++){

		sum[i][0]=0;

		for(int j=1;j<=X[i].size();j++){

			sum[i][j]=sum[i][j-1]+X[i][j-1]+2*(j-1);

		}

	}

	int dp[2001];

	fill(dp,dp+N+1,0);

	for(int i=0;i<10;i++){

		for(int j=2000-X[i].size();j>=0;j--){

			for(int k=0;k<=X[i].size();k++){

				dp[j+k]=max(dp[j+k],dp[j]+sum[i][k]);

			}

		}

	}

	printf("%d
",dp[K]);

    return 0;

}

