int H, W; string s[1009], t[3], x = "JOI";

int main() {

	cin >> H >> W;

	for (int i = 0; i < H; i++) cin >> s[i];

	cin >> t[0] >> t[1];

	int sum = 0;

	for (int i = 0; i < H - 1; i++) {

		for (int j = 0; j < W - 1; j++) {

			bool flag = true;

			for (int k = 0; k < 2; k++) {

				for (int l = 0; l < 2; l++) {

					if (s[i + k][j + l] != t[k][l]) flag = false;

				}

			}

			if (flag) sum++;

		}

	}

	int ret = 0;

	for (int i = 0; i < H; i++) {

		for (int j = 0; j < W; j++) {

			char e = s[i][j];

			int a[3] = { 0 }, z = -1;

			for (int c = 0; c < 3; c++) {

				if (x[c] == e) z = c;

				s[i][j] = x[c];

				for (int k = -1; k < 1 && i + k + 1 < H; k++) {

					if (i + k < 0) continue;

					for (int l = -1; l < 1 && j + l + 1 < W; l++) {

						if (j + l < 0) continue;

						bool flag = true;

						for (int m = 0; m < 2; m++) {

							for (int n = 0; n < 2; n++) {

								if (s[i + k + m][j + l + n] != t[m][n]) flag = false;

							}

						}

						if (flag) a[c]++;

					}

				}

			}

			for (int c = 0; c < 3; c++) ret = max(ret, sum + a[c] - a[z]);

			s[i][j] = e;

		}

	}

	cout << ret << endl;

	return 0;

}

#include <cstdio>

#include <algorithm>

#include <vector>



using namespace std;



typedef long long lint;



int main()

{

	int n;

	static int a[100000];

	static int s[200000], t[200000], next[2][200000];

	static pair<int, int> p[400000];

	static vector<int> bucket[300000];



	lint sum = 0;



	scanf("%d", &n);



	for (int i = 0; i < n; i++){

		scanf("%d", a + i);

		sum += a[i];

	}



	lint left = 0, right = sum / 3;



	while (left != right){

		lint mid = (left + right + 1) >> 1;

		lint sum2 = 0;

		int head = 0, tail = 0;

		bool ng = false;



		for (; head < n; head++){

			while (sum2 < mid){

				sum2 += a[tail++];

				if (tail >= n) tail -= n;

			}

			int i = head;

			s[i] = head, t[i] = tail;

			if (s[i] == t[i]) ng = true;

			if (t[i] < s[i]) t[i] += n;

			s[n + i] = s[i] + n, t[n + i] = t[i] + n;

			sum2 -= a[head];

		}

		if (ng){

			right = mid - 1;

			continue;

		}

		for (int i = 0; i < n * 3; i++) bucket[i].clear();



		for (int i = 0; i < n * 2; i++){

			bucket[t[i]].push_back(i);

			bucket[s[i]].push_back(n * 2 + i);

		}

		int ctr = 0;

		for (int i = 0; i < n * 3; i++){

			for (int j = 0; j < bucket[i].size(); j++){

				p[ctr++] = make_pair(i, bucket[i][j]);

			}

		}



		int last = -1;

		for (int i = n * 4 - 1; i >= 0; i--){

			int id = p[i].second;

			if (id < n * 2) next[0][id] = last;

			else {

				id -= n * 2;

				if (last < 0 || t[last] > t[id]) last = id;

			}

		}



		for (int k = 0; k + 1 < 2; k++){

			for (int i = 0; i < n * 2; i++){

				if (next[k][i] < 0) next[k + 1][i] = -1;

				else next[k + 1][i] = next[k][next[k][i]];

			}

		}



		int res = 0;

		for (int i = 0; i < n; i++){

			int tmp = 0, j = i;

			for (int k = 1; k >= 0; k--){

				int j2 = next[k][j];

				if (j2 >= 0 && t[j2] <= s[i] + n){

					j = j2;

					tmp |= 1 << k;

				}

			}

			if (res >= 3) break;

			res = max(res, tmp + 1);

		}

		if (res >= 3) left = mid;

		else right = mid - 1;

	}



	printf("%lld
", left);



	return (0);

}

#include <cstdio>

#include <iostream>

using namespace std;



int main()

{

	int InArray[200000] = {0};		// end is linked to start (Baumkuchen is round)

	int N;							// total data input

	int i;							// for counter

	int inputBuffer;				// buffer for input data

	int a1, a2, a3;					// the start index of each region

	long long sum;					// buffer for sum

	long long average, average2;	// sum / 3, (sum - region1) / 2

	long long a1_sum, a2_sum;		// sum of region1, region2

	long long MaxMin;				// final result



	scanf("%d", &N);

	for(i = 0; i < N; i++){

		scanf("%d", &inputBuffer);

		InArray[i] = inputBuffer;

		InArray[i + N] = inputBuffer;

	}





	// Calculate sum and average

	sum = 0;

	for(i = 0; i < N; i++){

		sum += InArray[i];

	}

	if(sum % 3 == 0){

		average = sum / 3;

	}else{

		average = sum / 3 + 1;

	}



	MaxMin = 0;

	for(a1 = 0; a1 < N; a1++){

		a1_sum = 0;

		for(a2 = a1 + 1; a2 < (a1 + N); a2++){

			a1_sum += InArray[a2 - 1];

			if(a1_sum < average) continue;



			if((sum - a1_sum) % 2 == 0){

				average2 = (sum - a1_sum) / 2;

			}else{

				average2 = (sum - a1_sum + 1) / 2;

			}



			a2_sum = 0;

			for(a3 = a2 + 1; a3 < (a1 + N); a3++){	// left 1 for a3_sum

				a2_sum += InArray[a3 -1];

				if(a2_sum < average2) continue;



				if(a2_sum - InArray[a3 -1] > MaxMin){

					MaxMin = a2_sum - InArray[a3 -1];

				}

				if(sum - a1_sum - a2_sum   > MaxMin){

					MaxMin = sum - a1_sum - a2_sum;

				}

				break;

			}

			break;

		}

	}



	printf("%lld
", MaxMin);



	return 0;

}

