#include <utility>

#include <cstdint>



using namespace std;



uint64_t N;

int8_t L[100000],_L[100000];



int main(void)

{

    cin >> N;

    int t;

    for(int i = 0;i < N;i++)

    {

        cin >> t;

        L[i] = t;

    }

    L[N] = -1;

    bool loop = true;

    uint64_t itr1 = 0,itr2 = 0;

    uint64_t result = 0;

    while(loop)

    {

        while(L[itr1] != L[itr1 + 1] && itr1 < N - 1)

        {

            itr1++;

        }

        itr2 = itr1 + 1;

        while(L[itr2] != L[itr2 + 1] && itr2 < N - 1)

        {

            itr2++;

        }

        memcpy(_L,L,sizeof(int8_t[100000]));

        for(uint64_t i = itr1 + 1;i <= itr2;i++)

        {

            if(L[i] == 0)

                _L[i] = 1;

            else if(L[i] == 1)

                _L[i] = 0;

        }

        uint64_t upper = itr1,downer = itr1,count = 1;

        while(upper > 0 && _L[upper] != _L[upper - 1])

        {

            upper--;

            count++;

        }

        while(downer < N - 1 && _L[downer] != _L[downer + 1])

        {

            downer++;

            count++;

        }

        result = max(result,count);

        itr1++;

        if(itr2 >= N - 1)

        {

            loop = false;

        }

    }

    cout << result << endl;

    return 0;

}

#include<cstdio>

#include<algorithm>

using namespace std;

typedef long long int ll;

static const int MAX_N = 2000;



int N;

ll A[MAX_N];

ll memo[MAX_N][2 * MAX_N];



ll memoize(int i, int j){

	if(memo[i][j] != -1) return memo[i][j];

	int i2 = (i == N - 1 ? 0 : i + 1);

	int j2 = (j == 0 ? N - 1 : j - 1);

	int itv = (i > j ? N + j - i : j - i);

	if((N - itv) % 2 == 1){

		if(i == j) return memo[i][j] = A[i];

		else return memo[i][j] = max(memoize(i2, j) + A[i], memoize(i, j2) + A[j]);

	}else{

		if(i == j) return memo[i][j] = 0LL;

		else if(A[i] > A[j]) return memo[i][j] = memoize(i2, j);

		else return memo[i][j] = memoize(i, j2);

	}

	return 0;

}



int main(){

	scanf("%d", &N);

	for(int i = 0; i < N; i++) scanf("%lld", &A[i]);

	fill(memo[0], memo[N], -1);

	for(int i = 0; i < N; i++){

		for(int j = 0; j < N; j++){

			memo[i][j] = memoize(i, j);

		}

	}

	ll res = 0LL;

	for(int i = 0; i < N; i++){

		for(int j = 0; j < N; j++){

			res = max(res, memo[i][j]);

		}

	}

	printf("%lld
", res);

	return 0;

}

