using namespace std;



bitset<MAX> b1;



void ComputePrimes(){

	b1.set();



	b1.reset(1);

	for(int i = 4; i <= 10000; ++i){

		for(int j = 2; j <= sqrt((double)i); ++j){

			if( i % j == 0 ){

				b1.reset( i );

				break;

			}

		}

	}

}



