const int coin[] = {1,5,10,50,100,500};

const int inf = 999999999;

int c[6],p;



int oturi(int x){

	int ret = 0;

	for(int i=5; i>=0 && x>0; i--){

		ret += (x/coin[i]);

		x -= (x/coin[i])*coin[i];

	}

	return ret;

}

int pay(int x){

	int ret = 0;

	for(int i=5; i>=0 && x>0; i--){

		ret += min(x/coin[i], c[i]);

		x -= min(x/coin[i],c[i]) * coin[i];

	}

	return x==0 ? ret : -1;

}

