int dfs(int s, int now, int maxi, int num){

  v[now] = true;



  for(int i=0;i<2;i++){

    if(!v[b[i][now]]){

      if(maxi == f[i][now])num++;

      else if(maxi < f[i][now]){

	maxi = f[i][now];

	num = 1;

      }

      if(b[i][now] == s)return num;

      return dfs(s,b[i][now],maxi,num);

    }

  }

  if(maxi == f[1][s])return num+1;

  else if(maxi < f[1][s])return 1;

  else return num;

}



