      int cbd=mm.front()&0x1ffffff;

      mm.pop();

      //int ub=upb(cbd);

      int ub=32-__builtin_clz(cbd);

      const vector<int> &ps=pats[ub];

      int sz=ps.size();

      for (int i=0; i<sz; i++){

	int nbd=cbd^ps[i];

	if (nbd==0){

	  for (int i=0; i<=dep; i++)

	    cout<<"myon";

	  cout<<endl;

	  goto _exit;

	}

	//cout<<"*** "<<nbd<<endl;

	if (close[nbd]) continue;

	close[nbd]=true;

	cls[cls_cnt++]=nbd;

	mm.push(((dep+1)<<25)|nbd);

      }

    }

  _exit:;

    for (int i=0; i<cls_cnt; i++)

      close[cls[i]]=false;

    cls_cnt=0;

  }

  return 0;

}

