struct SegTree{

	vi data;

	int size;

	SegTree(int _size){

		for(int i=1;;i*=2)

			if(i>=_size){

				size=i;

				break;

			}

		data.assign(size*2,0);

	}

	void add(int i,int x){

		for(int j=size+i;j;j/=2)

			data[j]+=x;

	}

	int sum(int a,int b,int i,int l,int r){

		if(r<=a || b<=l) return 0;

		if(a<=l && r<=b) return data[i];

		int m=(a+b)/2,res=0;

		if(a<m) res+=sum(a,b,i*2+0,l,m);

		if(m<b) res+=sum(a,b,i*2+1,m,r);

		return res;

	}

	int ith(int i){

		int j=1;

		while(j<size){

			if(data[j*2+0]>i)

				j=j*2+0;

			else{

				i-=data[j*2+0];

				j=j*2+1;

			}

		}

		return j-size;

	}

};



